# Try reading with different encodings, prioritizing common Korean encodings
try:
    df = pd.read_csv(DATA_FILE, encoding='utf-8')
except UnicodeDecodeError:
    try:
        df = pd.read_csv(DATA_FILE, encoding='cp949')
    except UnicodeDecodeError:
        try:
            df = pd.read_csv(DATA_FILE, encoding='euc-kr')
        except UnicodeDecodeError:
            # Fallback to latin1 if all else fails, though it might garble text
            df = pd.read_csv(DATA_FILE, encoding='latin1')

